#!/usr/bin/env bash

set -euo pipefail

here=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
temp_dir="$(mktemp -d)"
autogenerated="models/autogenerated.py"

cleanup() {
	rm -rf "$temp_dir"
}

trap cleanup EXIT ERR

main() {
	cd "$temp_dir"
	wget 'https://api.one.junction.dev/v1/api-docs.json'
	(
		echo 'from __future__ import annotations

from datetime import date
from enum import Enum
from typing import Any

from pydantic import (
	AwareDatetime,
	ConfigDict,
	Field,
	NaiveDatetime,
	RootModel,
	alias_generators,
	model_validator,
)
from pydantic import BaseModel as PydanticBase

AwareOrNaiveDatetime = AwareDatetime | NaiveDatetime


class BaseModel(PydanticBase):
	model_config = ConfigDict(
		alias_generator=alias_generators.to_camel,
		populate_by_name=True,
		from_attributes=True,
	)

		'
		docker run --rm -v "$PWD":/dir koxudaxi/datamodel-code-generator:0.25.4 \
			--input /dir/api-docs.json \
			--input-file-type openapi \
			--output-model-type pydantic_v2.BaseModel \
			--output /dir/temp.py \
			--use-union-operator \
			--target-python-version 3.11 \
			--snake-case-field

		grep -v '^#' <temp.py |
			grep -v '^from __future__ import annotations' |
			grep -v '^from datetime import date' |
			grep -v '^from enum import Enum' |
			grep -v '^from pydantic import' |
			sed 's/from datetime import date, datetime/from datetime import date/g' |
			sed -r 's/AwareDatetime/AwareOrNaiveDatetime/g' |
			sed -r 's/constr[^)]+\)/str/g'
	) >"$here/$autogenerated"

	awk '
/class LocalTime\(BaseModel\):/ {
	print
	print "	@model_validator(mode='\''before'\'')"
	print "	@classmethod"
	print "	def parse_time_string(cls, value: Any) -> Any:"
	print "		parts = map(int, value.split(\x27:\x27))"
	print "		fields = (\x27hour\x27, \x27minute\x27, \x27second\x27, \x27nano\x27)"
	print "		return {"
	print "			field: number"
	print "			for field, number in zip(fields, parts)"
	print "		}"
	print ""
	next
}
1' "$here/$autogenerated" >tmp
	if [[ "$OSTYPE" == "darwin"* ]]; then
		sed -i '' $'s/\t/    /g' tmp
	else
		sed -i $'s/\t/    /g' tmp
	fi

	mv tmp "$here/$autogenerated"

	cd "$here"
	pants fix lint check "$autogenerated"
	pants fix lint python/::
}

main
